INSERT INTO public.ad_reference_library (title, description, media_type, compatible_families, industry_tags, mood_tags, platform_tags, sealcam_analysis) VALUES
('Fast-Cut Product Montage', 'High-energy rapid cuts showcasing product from multiple angles with dynamic transitions', 'video', '{F8_creative_cloner}', '{ecommerce,fashion,beauty}', '{energetic,dynamic,urgent}', '{tiktok,instagram_reels}', '{"scenes":[{"subject":"product close-up","action":"rapid angle change","camera":"quick cuts","duration_s":2},{"subject":"product in use","action":"fast montage","camera":"handheld dynamic","duration_s":3}],"pacing":"fast","total_duration_s":15}'),
('Luxury Slow Reveal', 'Elegant slow-motion product reveal with premium lighting and minimal composition', 'video', '{F8_creative_cloner,F5_cinematic}', '{luxury,jewelry,watches,automotive}', '{luxurious,elegant,dramatic}', '{youtube_ads,instagram_reels}', '{"scenes":[{"subject":"dark silhouette","action":"slow light reveal","camera":"smooth dolly","duration_s":5},{"subject":"product detail","action":"macro exploration","camera":"slow orbit","duration_s":5}],"pacing":"slow","total_duration_s":15}'),
('UGC Reaction Style', 'Authentic reaction-style ad showing genuine surprise and delight with product', 'video', '{F8_creative_cloner}', '{beauty,skincare,food,gadgets}', '{authentic,surprised,warm}', '{tiktok,instagram_reels}', '{"scenes":[{"subject":"person opening package","action":"genuine reaction","camera":"selfie cam","duration_s":5},{"subject":"product demo","action":"excited showcase","camera":"handheld close","duration_s":5}],"pacing":"medium","total_duration_s":15}'),
('Split-Screen Comparison', 'Side-by-side comparison format showing your product vs alternatives', 'image', '{F7_ad_creator}', '{saas,technology,beauty,supplements}', '{confident,analytical,bold}', '{facebook,instagram}', '{"layout":"split_screen","left":"competitor/old way","right":"your product/new way","emphasis":"contrast and clarity"}'),
('Testimonial Quote Card', 'Clean testimonial layout with customer quote, photo, and star rating', 'image', '{F7_ad_creator}', '{general,saas,ecommerce,services}', '{trustworthy,warm,professional}', '{facebook,instagram,linkedin}', '{"layout":"quote_card","elements":["customer_photo","quote_text","star_rating","brand_logo"],"style":"clean minimal with social proof emphasis"}'),
('Story-Driven Brand Film', 'Cinematic narrative arc with emotional storytelling and brand integration', 'video', '{F5_cinematic}', '{lifestyle,automotive,luxury,nonprofit}', '{inspirational,emotional,epic}', '{youtube_ads,facebook}', '{"scenes":[{"subject":"establishing shot","action":"set emotional tone","camera":"wide cinematic","duration_s":5},{"subject":"character journey","action":"narrative progression","camera":"tracking shots","duration_s":15},{"subject":"brand reveal","action":"emotional payoff","camera":"slow push-in","duration_s":5}],"pacing":"cinematic","total_duration_s":30}'),
('Problem-Agitate-Solve Ad', 'Classic direct response structure showing pain point, amplifying it, then presenting solution', 'video', '{F8_creative_cloner}', '{health,fitness,finance,saas,supplements}', '{urgent,empathetic,confident}', '{facebook,youtube_ads,instagram_reels}', '{"scenes":[{"subject":"pain point visualization","action":"show frustration","camera":"close-up emotion","duration_s":5},{"subject":"agitation","action":"amplify problem","camera":"dramatic angles","duration_s":5},{"subject":"solution reveal","action":"product as hero","camera":"bright confident","duration_s":5}],"pacing":"building","total_duration_s":15}'),
('Carousel Education Post', 'Multi-slide educational content with branded design system', 'image', '{F4_social_content}', '{education,coaching,saas,marketing}', '{informative,professional,engaging}', '{instagram,linkedin}', '{"layout":"carousel","slides":["hook_slide","insight_1","insight_2","insight_3","cta_slide"],"style":"consistent brand template with progressive disclosure"}'),
('Influencer Unboxing', 'Authentic unboxing experience with genuine first impressions', 'video', '{F8_creative_cloner}', '{ecommerce,beauty,gadgets,fashion,food}', '{excited,authentic,curious}', '{tiktok,youtube_shorts,instagram_reels}', '{"scenes":[{"subject":"sealed package","action":"build anticipation","camera":"close-up hands","duration_s":5},{"subject":"unboxing reveal","action":"genuine reaction","camera":"POV selfie","duration_s":5},{"subject":"first use","action":"authentic testing","camera":"handheld close","duration_s":5}],"pacing":"building","total_duration_s":15}'),
('Bold Statistic Ad', 'Data-driven ad leading with a compelling statistic and social proof', 'image', '{F7_ad_creator}', '{finance,health,saas,education,fitness}', '{bold,confident,analytical}', '{facebook,linkedin,instagram}', '{"layout":"stat_hero","elements":["large_number","context_text","product_image","cta_button"],"style":"bold typography with data visualization accent"}');
